class Solution {
    public int countGoodSubstrings(String s) {
        int answer = 0;
        for (int i = 0; i + 2 < s.length(); i++) {
            char first = s.charAt(i);
            char second = s.charAt(i + 1);
            char third = s.charAt(i + 2);
            if (first != second && first != third && second != third) {
                answer++;
            }
        }
        return answer;
    }
}

class Solution {
    public int countGoodSubstrings(String s) {
        int[] frequency = new int[26];
        int duplicateKinds = 0;
        int answer = 0;

        for (int right = 0; right < s.length(); right++) {
            int added = s.charAt(right) - 'a';
            frequency[added]++;
            if (frequency[added] == 2) {
                duplicateKinds++;
            }

            if (right >= 3) {
                int removed = s.charAt(right - 3) - 'a';
                if (frequency[removed] == 2) {
                    duplicateKinds--;
                }
                frequency[removed]--;
            }

            if (right >= 2 && duplicateKinds == 0) {
                answer++;
            }
        }
        return answer;
    }
}

class Solution {
    public int countGoodSubstrings(String s) {
        int answer = 0;
        for (int i = 0; i + 2 < s.length(); i++) {
            int mask = 0;
            for (int j = i; j < i + 3; j++) {
                mask |= 1 << (s.charAt(j) - 'a');
            }
            if (Integer.bitCount(mask) == 3) {
                answer++;
            }
        }
        return answer;
    }
}

class Solution {
    public int countGoodSubstrings(String s) {
        int answer = 0;
        for (int i = 0; i + 2 < s.length(); i++) {
            java.util.HashSet<Character> window = new java.util.HashSet<>();
            window.add(s.charAt(i));
            window.add(s.charAt(i + 1));
            window.add(s.charAt(i + 2));
            if (window.size() == 3) {
                answer++;
            }
        }
        return answer;
    }
}
